<script setup lang="ts">
import { ref,onMounted } from 'vue';
import { request } from '../crm-api';
import type { QuoteDraft } from './QuotationEditor.vue';
const props=defineProps<{inquiries:{id:number;company:string;contact_name:string}[];locale:string}>();
const emit=defineEmits<{inquiry:[id:number];draft:[record:QuoteDraft];inbox:[]}>();
const tx=(z:string,e:string)=>props.locale==='zh'?z:e;
const data=ref<{tasks:{id:string;inquiry_id:number;title:string;due_at:string|null}[];new_inquiries:{id:number;created_at:string}[];drafts:QuoteDraft[];unassigned:number}>({tasks:[],new_inquiries:[],drafts:[],unassigned:0});
const error=ref('');
onMounted(async()=>{try{data.value=await request('workbench')}catch(e){error.value=e instanceof Error?e.message:String(e)}});
function company(id:number){return props.inquiries.find(i=>i.id===id)?.company||'#'+id}
</script>
<template><section class="workbench"><header><span class="eyebrow">{{tx('每日工作','YOUR DAILY WORKSPACE')}}</span><h2>{{tx('把下一步，安排清楚。','A clear next step.')}}</h2><p>{{tx('新需求、正在整理的报价，以及邮件里已经提出的跟进事项。','New enquiries, proposals in progress and follow-ups from your conversations.')}}</p></header><p v-if="error" class="work-error">{{error}}</p><div class="work-counters"><button type="button" :disabled="!data.new_inquiries.length" @click="emit('inquiry',data.new_inquiries[0].id)"><span>{{tx('新询价','NEW ENQUIRIES')}}</span><strong>{{data.new_inquiries.length}}</strong><small>{{tx('需要了解客户需求','Ready for a conversation')}} ↗</small></button><button type="button" :disabled="!data.drafts.length" @click="emit('draft',data.drafts[0])"><span>{{tx('报价草稿','WORKING PROPOSALS')}}</span><strong>{{data.drafts.length}}</strong><small>{{tx('继续未完成的方案','Continue where you left off')}} ↗</small></button><button type="button" @click="emit('inbox')"><span>{{tx('待关联邮件','UNLINKED EMAILS')}}</span><strong>{{data.unassigned}}</strong><small>{{tx('关联后自动归档与摘要','Link once, then process automatically')}} ↗</small></button></div><div class="work-columns"><section><h3>{{tx('待跟进事项','FOLLOW-UP ACTIONS')}}<span>{{data.tasks.length}}</span></h3><button v-for="task in data.tasks" :key="task.id" type="button" class="work-row" @click="emit('inquiry',task.inquiry_id)"><div><strong>{{task.title}}</strong><small>{{company(task.inquiry_id)}} · {{task.due_at||tx('未指定日期','No date specified')}}</small></div><span>↗</span></button><p v-if="!data.tasks.length" class="work-empty">{{tx('暂无待办。邮件中的明确事项会自动整理到这里。','No pending actions. Follow-ups are extracted automatically from messages.')}}</p></section><section><h3>{{tx('继续报价','CONTINUE A PROPOSAL')}}<span>{{data.drafts.length}}</span></h3><button v-for="draft in data.drafts" :key="draft.id" type="button" class="work-row" @click="emit('draft',draft)"><div><strong>{{company(draft.inquiry_id)}}</strong><small>{{draft.quote_id?'Q-'+draft.quote_id+' / '+tx('修订','Revision'):tx('新报价草稿','New quotation draft')}}</small></div><span>↗</span></button><p v-if="!data.drafts.length" class="work-empty">{{tx('从询价创建报价，草稿会自动保存在这里。','Start a quote from an enquiry. Your working draft is kept here.')}}</p><h3 class="recent-heading">{{tx('新询价','RECENT ENQUIRIES')}}</h3><button v-for="item in data.new_inquiries.slice(0,5)" :key="item.id" type="button" class="work-row" @click="emit('inquiry',item.id)"><div><strong>{{company(item.id)}}</strong><small>{{props.inquiries.find(i=>i.id===item.id)?.contact_name}}</small></div><span>↗</span></button></section></div></section></template>
<style scoped>
.workbench{padding:18px 0;color:#1c2922}.eyebrow{font-size:10px;letter-spacing:.14em;color:#82917f}.workbench>header h2{font-size:clamp(26px,3vw,38px);font-weight:500;letter-spacing:-.03em;margin:18px 0 14px}.workbench>header p{font-size:13px;line-height:1.8;color:#84917d;max-width:560px;margin:0}.work-counters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:38px 0 44px;gap:18px}.work-counters button{display:block;text-align:left;padding:25px;border:1px solid #e3e8df;border-radius:6px;background:#fff;color:#1c2922;cursor:pointer;font-family:var(--font-body)}.work-counters button:first-child{background:#183b2c;border-color:#183b2c;color:#fff}.work-counters span{display:block;font-size:10px;letter-spacing:.08em;opacity:.65}.work-counters strong{display:block;font-size:44px;font-weight:500;line-height:1;margin:24px 0 20px;font-variant-numeric:tabular-nums}.work-counters small{font-size:11px;opacity:.65}.work-counters button:hover{border-color:#769d6d}.work-counters button:disabled{cursor:default}.work-columns{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:44px}.work-columns h3{display:flex;justify-content:space-between;font-size:11px;font-weight:600;letter-spacing:.08em;margin:0 0 22px;color:#52684a}.work-columns h3 span{color:#91a08a}.work-row{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;padding:18px 0;background:transparent;border:0;border-top:1px solid #e3e8df;border-radius:0;color:#1c2922;text-align:left;font-family:var(--font-body);cursor:pointer}.work-row strong{display:block;font-size:13px;font-weight:500;line-height:1.7}.work-row small{display:block;font-size:10px;color:#8a9881;margin-top:6px}.work-row>span{color:#94a388}.work-empty{font-size:12px;line-height:1.9;color:#8a9881;max-width:360px}.recent-heading{margin-top:34px!important}.work-error{color:#a25336;font-size:13px}@media(max-width:700px){.work-counters{gap:10px;margin:28px 0}.work-counters button{padding:16px 12px}.work-counters strong{font-size:34px;margin:18px 0}.work-counters small{font-size:10px;line-height:1.6}.work-counters span{font-size:9px}.work-columns{grid-template-columns:1fr;gap:30px}}
</style>
